import unittest
from candidate import will_it_fly

class TestWillItFly(unittest.TestCase):
    def test_balanced_and_within_weight_limit(self):
        self.assertTrue(will_it_fly([3, 2, 3], 9))

    def test_unbalanced_but_within_weight_limit(self):
        self.assertFalse(will_it_fly([1, 2], 5))

    def test_balanced_but_exceeds_weight_limit(self):
        self.assertFalse(will_it_fly([3, 2, 3], 1))

    def test_single_element_within_weight(self):
        self.assertTrue(will_it_fly([3], 5))

    def test_empty_list_within_zero_weight(self):
        self.assertTrue(will_it_fly([], 0))

    def test_empty_list_with_negative_weight(self):
        self.assertFalse(will_it_fly([], -1))

    def test_boundary_condition_sum_equals_weight(self):
        self.assertTrue(will_it_fly([2, 1, 2], 5))

    def test_negative_values_in_palindrome_within_weight(self):
        self.assertTrue(will_it_fly([-2, 0, -2], 3))

    def test_float_elements_and_weight_within_limit(self):
        self.assertTrue(will_it_fly([1.5, 2.5, 1.5], 6.0))

    def test_float_sum_equals_weight_boundary(self):
        self.assertTrue(will_it_fly([1.5, 2.5, 1.5], 5.5))

    def test_none_value_for_q_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly(None, 5)

    def test_none_value_for_w_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly([1, 2, 1], None)

    def test_non_list_q_value_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly("not a list", 5)

    def test_non_numeric_elements_in_q_raises_type_error(self):
        with self.assertRaises(TypeError):
            will_it_fly([1, "2", 1], 5)

if __name__ == '__main__':
    unittest.main()
